learn=[('Package reusable capabilities', 'A local plugin can bundle skills, agent definitions, hooks and MCP servers. Inspect the actual classroom bundle in the file viewer.'), ('Load local roots explicitly', 'Pass plugins: [{type: "local", path}]. Compare an absolute path with a path relative to the query cwd. The path must identify the plugin root; tilde expansion and marketplace downloading are not performed here.'), ('Verify actual initialization', 'Inspect init.plugins, skills, slash_commands and plugin_errors. The app also records agent discovery and actual MCP connection metadata. Built-in plugin entries can appear independently.'), ('Dispatch namespaced skills', 'Send /classroom-tools:greet or /classroom-notes:greet. Both plugins contain greet, but their namespaces select different instructions and response markers.'), ('Inspect optional manifests and failures', 'Compare a working manifest-free plugin with a nonexistent root and a corrupt manifest. A completed greeting does not mean the requested plugin loaded.'), ('Share a bundle across projects', 'Load the same unchanged classroom-tools directory from two private working projects. Verify different project facts and the same plugin path. Agent discovery and MCP connection are observed; subagent and MCP tool execution are not demonstrated.')]
body='<div class="flow"><div><b>01 · Package</b><p>One folder, reusable components</p></div><span>→</span><div><b>02 · Load</b><p>Local root and namespace</p></div><span>→</span><div><b>03 · Verify</b><p>Initialization and actual results</p></div></div><section class="panel" id="controls"><h2>Explore local plugins in SDK sessions</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Plugin experiment</label><select id="mode"><option value="absolute">Load classroom-tools · absolute local root</option><option value="relative">Load the same plugin · relative to cwd</option><option value="pair">Two plugins · two namespaced greet skills</option><option value="no-manifest">classroom-lite · optional manifest omitted</option><option value="missing">Missing local plugin root · inspect diagnostics</option><option value="invalid">Corrupt plugin.json · inspect diagnostics</option><option value="share">Share the unchanged plugin across projects A and B</option></select><button id="run" class="primary" disabled>Load plugins and run →</button><p class="meta">Each experiment uses private classroom projects. Plugin roots and prompts are fixed, and your API key stays on the server.</p></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>SDK reported cost: <strong id="cost">—</strong></p><p class="meta">Latest session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Only local plugin roots are configured. settingSources: [] and skills: [] are separate from explicit plugin loading and direct namespaced dispatch.</p></section></div><section class="step" id="discovery-panel"><h2>Actual plugin and component discovery</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>The init projection preserves plugins, skills, command names, agents, MCP status and plugin_errors. The presence of a definition or a connected server is not proof that an agent or tool was invoked.</p></section><section class="step" id="evidence-panel"><h2>Actual plugin evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Completed Reads and response markers identify observed skill behavior. Hook receipts are written by the plugin’s actual SessionStart process into an owned private file. Plugin source hashes establish that the shared bundle stayed unchanged.</p></section><section class="step" id="fixtures-panel"><h2>The actual plugin directory contents</h2><label for="fixture">Bundled file</label><select id="fixture"></select><pre id="fixture-content" role="region" aria-label="Actual plugin file contents">Run an experiment to inspect the plugin files.</pre><p>The classroom-tools bundle includes a skill, agent definition, hook and local MCP server. classroom-notes supplies a second greet namespace. classroom-lite demonstrates a plugin with no manifest. No marketplace download is performed.</p></section><section class="step" id="init-panel"><h2>Latest actual system/init projection</h2><pre class="json-view"><code id="init" class="language-json">{}</code></pre></section><section class="step" id="run-history"><h2>Compare this browser’s experiments</h2><div class="table"><table><thead><tr><th>Mode</th><th>Loaded plugins</th><th>Actual response markers</th><th>Completed Reads</th><th>Hook receipts</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download actual observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages and tools</h2><ul id="events"></ul></section>'
document('/','Plugins <em>package it all.</em>','Load local bundles, dispatch namespaced skills, inspect real component metadata and share one plugin across projects.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Connect the plugin directory layout to actual SDK loading, namespaced invocation and diagnostics.',cards(learn)+actions(('/run.html','Configure and run →'),('/architecture.html','Explore the UML →')))
env=(APP/'.env.example').read_text(encoding='utf-8').strip()
runsteps=[('Prepare the project', 'Use Node.js 24+, npm, an Anthropic API key and model access. On Windows, install Git for the Bash runtime used by the SDK.', 'cd .\\agent-sdk\\lesson20-plugins'), ('Install and configure', 'Install locked dependencies, preserve an existing .env and enter your key locally. The bundled MCP process uses the installed official MCP SDK.', 'npm ci\nif (!(Test-Path .env)) {\n  Copy-Item .env.example .env\n}\nnotepad .env'), ('Start the app', 'Open port 3120 and keep the terminal running. Navigate among the lab, learning goals, setup, UML and source walkthrough.', 'npm start\n# http://127.0.0.1:3120'), ('Load and verify', 'Run Absolute and Relative. Inspect the actual local roots, initialization, completed manifest Read and SessionStart hook receipt. Agent definitions and MCP connections are metadata observations, not execution claims.', 'npm run sample:env -- absolute\nnpm run sample:env -- relative'), ('Compare namespaces and layout', 'Run Pair to dispatch two greet skills using different prefixes. Then run No manifest to observe component discovery without plugin.json. Inspect the actual saved plugin files.', 'npm run sample:env -- pair\nnpm run sample:env -- no-manifest'), ('Troubleshoot and share', 'Run Missing and Invalid. Inspect the requested plugin’s absence and plugin_errors separately from an ordinary greeting result. Then run Share: projects A and B use the same unchanged plugin directory.', 'npm run sample:env -- missing\nnpm run sample:env -- invalid\nnpm run sample:env -- share\nnpm test')]
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>The startup script loads .env; shell variables take precedence. Restart after edits. No Managed Agents resource ID is required. Never share your real key.</p></section><section class="note"><h3>Troubleshooting</h3><p>If another service occupies the port, change PORT. A second start of this app prints its existing URL. On Windows set CLAUDE_CODE_GIT_BASH_PATH if Bash cannot be found. Keep optional npm dependencies enabled. A failed SDK result is retained as a failure. Check the plugin root, manifest JSON, readability and existence. Verify the namespaced skill layout. An ordinary successful answer does not establish plugin loading.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install, set your key, then observe genuine plugin loading and invocation behavior.',body)
specs=[('Validate the plugin experiment', 'src/agent.ts', 'if (!value ||', 'Accept a listed classroom mode. Browser input cannot supply arbitrary plugin code, remote locations or filesystem paths.', 0, 1), ('Prepare two private projects', 'src/agent.ts', 'for (const [cwd, project]', 'Write distinct project manifests in owned private directories. The shared plugin is kept outside those projects and is not modified.', 1, 4), ('Resolve the intended local root', 'src/agent.ts', 'const first = resolve(PLUGINS', 'Compare a fixed absolute plugin root with a path relative to the query working directory. The selected path identifies the root, not the skills subdirectory.', 1, 3), ('Pass local plugin configuration', 'src/agent.ts', 'plugins: pluginPaths', 'Configure each plugin with type local. Explicit plugin loading is separate from filesystem settings and model skill scope.', 1, 2), ('Dispatch the namespaced prompt', 'src/agent.ts', 'const prompt=[', 'Send the plugin-prefixed greet name as an ordinary prompt. Its argument identifies the exact project manifest the skill may read.', 1, 2), ('Run the actual SDK query', 'src/agent.ts', 'const run=query({prompt,options});', 'The SDK runtime loads the local bundle and manages Claude’s native message and tool loop. The host does not fabricate a plugin response.', 1, 2), ('Inspect loaded plugins and diagnostics', 'src/agent.ts', 'phase,plugins:message.plugins', 'Preserve actual plugin rows and plugin_errors. Built-in entries may coexist with the classroom plugin; a missing requested root is still a loading failure.', 2, 1), ('Inspect namespaced components', 'src/agent.ts', 'skills:message.skills', 'Read namespaced skills and commands, discovered agents and MCP connection status. Discovery and connection do not establish agent or tool invocation.', 3, 2), ('Observe the plugin’s real hook', 'plugins/classroom-tools/hooks/observe.cjs', 'const receipt=process.env.PLUGIN_LAB_RECEIPT;', 'The packaged SessionStart hook writes a receipt to the private path supplied by the host. It does not write into the shared plugin directory.', 3, 4), ('Connect the packaged local MCP server', 'plugins/classroom-tools/mcp/server.mjs', 'await server.connect', 'The bundled stdio server uses the official MCP SDK. This lesson verifies its connection metadata and does not call its tool.', 3, 2), ('Record completed manifest Reads', 'src/agent.ts', 'if(input.hook_event_name==="PostToolUse"', 'A successful host tool hook records the actual project-manifest Read. Response markers are checked separately from these completed calls.', 2, 4), ('Reuse the same bundle across projects', 'src/agent.ts', 'const stages=c.mode===', 'The Share experiment starts queries in project A and project B using the same plugin root. Actual project facts and unchanged source hashes demonstrate the reuse.', 1, 2), ('Format actual assistant answers', 'src/client.ts', 'if (e.type === "answer") renderMarkdown', 'Parse and sanitize real Markdown answers. Keep plugin metadata, diagnostics, hook receipts and result text distinct.', 1, 0)]
steps=[];arrows=[];lanes=['Student UI','Node host','SDK + Claude','Plugin bundle','Owned projects']
for n,(title,source,anchor,explanation,a,b) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 count={1:2,2:2,3:3,4:3,5:1,6:2,7:1,8:2,9:8,10:1,11:2,12:1,13:3}.get(n,1);code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='javascript' if source.endswith(('.cjs','.mjs')) else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 20 · Local roots → namespaces → verified reuse</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="M{x1} {y} H{x2}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen plugin loading, component discovery and sharing steps"></div>'+walk)
reference=[('Trust the bundle you load', 'Plugins can start hooks and local MCP processes. This app loads only the included trusted classroom code and fixed paths. The browser cannot select arbitrary plugins.'), ('Optional manifest', 'The manifest declares a stable name and version, but layout can supply components without it. classroom-lite demonstrates this observed loader behavior.'), ('MCP and agent evidence', 'The app records the plugin’s discovered coach definition and connected local stdio server. It does not invoke a subagent or the MCP tool. The hook receipt, however, comes from an actual executed SessionStart process.'), ('MCP configuration', 'strictMcpConfig is false here so the plugin’s packaged MCP definition can load. Homes and SDK configuration are private; filesystem setting sources are empty and claude.ai MCP is disabled. Model tool guards still reject every target except the project manifest.'), ('Troubleshooting', 'Check root path, JSON syntax, readability, existence, namespace and skills/name/SKILL.md. The SDK may report missing paths in plugin_errors while continuing the ordinary conversation. Built-in plugins may still be listed.'), ('Local paths and distribution', 'The SDK receives local directories. Download a marketplace or repository plugin before passing its local root. The app demonstrates sharing one local directory across two projects; it does not publish a marketplace plugin.')]
document('/walkthrough.html','How the app <em>was built.</em>','Thirteen coloured source excerpts connect loading, invocation, components, diagnostics and sharing.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 20 · Plugins: package it all\n\nBased on Lesson20_Plugins.pptx. Five linked student pages, large text and coloured source code at all 13 UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson20-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson20-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations, use `cd .\\agent-sdk\\lesson20-plugins` instead of cloning. Open http://127.0.0.1:3120. Keep the terminal running. Node.js 24+ and model access are required.\n\n## Create your .env file\n\nPreserve an existing file or copy .env.example. Enter your key locally. Restart after edits. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo Managed Agents resource ID is needed. On Windows configure Git Bash if necessary. Do not commit the real .env.\n\n## Run the experiments\n\n'
for a,b,c in runsteps[3:]:readme+=f'### {a}\n\n{b}\n\n```powershell\n{c}\n```\n\n'
readme+='## How the app was built\n\n'
for s in steps:readme+=f'### {s["number"]}. {s["title"]}\n\n{s["explanation"]}\n\nSource: `{s["source"]}`, lines {s["firstLine"]}–{s["lastLine"]}. Selected excerpt; surrounding code omitted.\n\n```typescript\n{s["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\nThe controls show actual results rather than saved model answers. Session transcripts, local runtime files, dependencies and all media remain excluded from Git.\n\n## References\n\n- [Plugins in the SDK](https://code.claude.com/docs/en/agent-sdk/plugins)\n- [Plugin structure reference](https://code.claude.com/docs/en/plugins-reference)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate the five student pages with `python scripts/build-pages.py`.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 20 pages with 13 source-matched UML steps.')
